#!/bin/bash
# Prueba de solo lectura del playbook evaluar-imagenes-ocp.yml contra el SNO. Sin secretos en la salida.
W=/tmp/imgocp-$$; mkdir -p $W && cd $W
echo "" | base64 -d | tar xzf -
python3 -m venv $W/venv >/dev/null && $W/venv/bin/pip install -q "ansible-core>=2.15,<2.16" kubernetes 2>&1 | grep -v -i "warning\|upgrade" | tail -2
export PATH=$W/venv/bin:$HOME/openshift/sno/bin:$PATH ANSIBLE_COLLECTIONS_PATH=$W/col ANSIBLE_LOCALHOST_WARNING=False
ansible-galaxy collection install -q -p $W/col -r imagenes-ocp/collections/requirements.yml 2>&1 | grep -v -i warning | tail -2
cd imagenes-ocp; ansible-playbook --syntax-check evaluar-imagenes-ocp.yml 2>&1 | tail -1
T0=$(date +%s)
ansible-playbook evaluar-imagenes-ocp.yml -e ocp_kubeconfig=$HOME/openshift/sno/instalar/auth/kubeconfig -e reporte_dir=$W/out 2>&1   | grep -v -i -E "token|password|secret|bearer|certificate-authority-data|client-key" | grep -E '^(TASK|ok|changed|fatal|failed|skipping|PLAY RECAP|localhost)|"(Clúster|Registro|Espacio|Caché|Bloque|Aviso|Reporte|No disponible|msg)' | cut -c1-260
echo "DURACION $(($(date +%s)-T0))s"
ls -la $W/out | awk '{print $5, $9}'
echo "== estados"; python3 -c "
import json,glob,collections;e=json.load(open(glob.glob('$W/out/*.json')[0]))
print(collections.Counter(f['estado'] for f in e['imagenes']).most_common())
print([(b['id'],b['cantidad'],b['espacio']) for b in e['bloques']])
for b in e['bloques']: print(b['id'], [(g['grupo'],g['cantidad'],g['espacio']) for g in b['por_grupo']][:12])
"
echo "== HTML_B64_INICIO"; gzip -9c $W/out/*.html | base64 -w0; echo; echo "== HTML_B64_FIN"
echo "debug ns restantes: $(oc --kubeconfig $HOME/openshift/sno/instalar/auth/kubeconfig get ns --no-headers | grep -c openshift-debug)"
cd /; rm -rf $W
